import { deduplicate, type DeduplicationOptions } from '@/utils/requestDeduplicator';

const API_URL = import.meta.env.PROD
    ? '' // Relative path for unified deployment
    : `http://${window.location.hostname}:3000`;

type RequestMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

/**
 * Configuration for request deduplication
 *
 * Controls which endpoints should use request deduplication to prevent
 * duplicate concurrent API calls. Deduplication is useful for expensive
 * operations (AI calls, image processing) but should be avoided for
 * auth flows, real-time updates, and streaming endpoints.
 */
interface DeduplicationConfig {
    /** Endpoint patterns that should be deduplicated */
    include: (string | RegExp)[];
    /** Endpoint patterns that should never be deduplicated */
    exclude: (string | RegExp)[];
}

/**
 * Default deduplication configuration
 *
 * INCLUDED (deduplicated):
 * - /api/ai/* - AI chat and generation endpoints (expensive, prone to double-clicks)
 * - /api/user/api-keys, /api/user/profile, /api/user/preferences - User data reads
 * - /api/chat/conversations*, /api/chat/messages* - Chat data operations
 * - /api/images/* - Image processing operations
 * - /api/replicate/* - Replicate AI operations (expensive)
 *
 * EXCLUDED (not deduplicated):
 * - /api/auth/* - Authentication flows (should not be cached)
 * - /api/**/stream* - Streaming endpoints (incompatible with deduplication)
 * - /api/user/last-login - Intentional action tracking
 *
 * Rationale: Deduplication prevents wasted credits and bandwidth when users
 * rapidly click "Generate" or when the voice agent fires similar requests.
 * Auth endpoints are excluded to ensure proper session handling and security.
 */
const DEDUPLICATION_CONFIG: DeduplicationConfig = {
    include: [
        /^\/api\/ai\/.*/,              // All AI endpoints
        /^\/api\/user\/api-keys/,      // API key management
        /^\/api\/user\/profile/,       // Profile reads/updates
        /^\/api\/user\/preferences/,   // Preferences
        /^\/api\/user\/voice-key/,     // Voice key
        /^\/api\/chat\/.*/,            // Chat conversations and messages
        /^\/api\/images\/.*/,          // Image operations
        /^\/api\/replicate\/.*/,       // Replicate AI operations
    ],
    exclude: [
        /^\/api\/auth\/.*/,            // All auth endpoints (login, signup, logout, etc.)
        /.*stream.*/i,                 // Any streaming endpoints
        /^\/api\/user\/last-login/,    // Intentional action tracking
    ],
};

/**
 * Determines if an endpoint should use request deduplication
 *
 * @param endpoint - The API endpoint path (e.g., '/api/ai/chat')
 * @returns true if the endpoint should be deduplicated, false otherwise
 *
 * @example
 * shouldDeduplicate('/api/ai/chat')        // true - AI endpoint
 * shouldDeduplicate('/api/auth/login')     // false - auth endpoint
 * shouldDeduplicate('/api/user/profile')   // true - user data endpoint
 */
function shouldDeduplicate(endpoint: string): boolean {
    // Check exclusions first (highest priority)
    for (const pattern of DEDUPLICATION_CONFIG.exclude) {
        if (typeof pattern === 'string' ? endpoint === pattern : pattern.test(endpoint)) {
            return false;
        }
    }

    // Check inclusions
    for (const pattern of DEDUPLICATION_CONFIG.include) {
        if (typeof pattern === 'string' ? endpoint === pattern : pattern.test(endpoint)) {
            return true;
        }
    }

    // Default: do not deduplicate (conservative approach)
    return false;
}

interface ApiRequestOptions {
    method?: RequestMethod;
    body?: any;
    headers?: Record<string, string>;
    /**
     * If true, bypasses request deduplication for this specific request.
     * Useful for retries, forced refreshes, or intentional duplicate requests.
     *
     * @default false
     *
     * @example
     * // Force a fresh API call even if identical request is in-flight
     * api.post('/api/ai/generate', { prompt: 'hello' }, { bypassDeduplication: true });
     */
    bypassDeduplication?: boolean;
}

export class ApiError extends Error {
    status: number;
    constructor(message: string, status: number) {
        super(message);
        this.status = status;
    }
}

async function request<T>(endpoint: string, options: ApiRequestOptions = {}): Promise<T> {
    const { method = 'GET', body, headers = {}, bypassDeduplication = false } = options;

    // Extract the core request logic into an executor function for deduplication
    const executor = async (): Promise<T> => {
        const config: RequestInit = {
            method,
            headers: {
                'Content-Type': 'application/json',
                ...headers,
            },
            credentials: 'include', // Important for Lucia session cookies
        };

        if (body) {
            config.body = JSON.stringify(body);
        }

        // Handle relative vs absolute URLs
        // If we serve frontend from the same domain as backend (e.g. via Nginx or similar), relative is fine.
        // But typically we have separated deployments here.
        const url = endpoint.startsWith('http') ? endpoint : `${API_URL}${endpoint}`;

        const response = await fetch(url, config);

        if (!response.ok) {
            let errorMessage = 'An unknown error occurred';
            try {
                const errorData = await response.json();
                errorMessage = errorData.error || response.statusText;
            } catch (e) {
                errorMessage = await response.text();
            }
            throw new ApiError(errorMessage, response.status);
        }

        // Handle empty responses (e.g. 204)
        if (response.status === 204) {
            return {} as T;
        }

        try {
            return await response.json();
        } catch (e) {
            // Fallback if not JSON
            return {} as T;
        }
    };

    // Check if this endpoint should use request deduplication
    // Skip deduplication if explicitly bypassed or endpoint is not in config
    if (!bypassDeduplication && shouldDeduplicate(endpoint)) {
        // Log in development mode
        if (import.meta.env.DEV) {
            console.log(`[Dedup] Applying deduplication to ${method} ${endpoint}`);
        }
        // Use deduplication wrapper for applicable endpoints
        return deduplicate<T>(executor, endpoint, method, body);
    }

    // Log bypass or exclusion in development mode
    if (import.meta.env.DEV) {
        if (bypassDeduplication) {
            console.log(`[Dedup] Bypassed for ${method} ${endpoint} (explicit bypass flag)`);
        } else {
            console.log(`[Dedup] Not deduplicated - ${method} ${endpoint} (endpoint not in config)`);
        }
    }

    // For non-deduplicated endpoints or bypassed requests, execute normally
    return executor();
}

export const api = {
    get: <T>(endpoint: string, options?: Omit<ApiRequestOptions, 'method' | 'body'>) =>
        request<T>(endpoint, { ...options, method: 'GET' }),
    post: <T>(endpoint: string, body: any, options?: Omit<ApiRequestOptions, 'method' | 'body'>) =>
        request<T>(endpoint, { ...options, method: 'POST', body }),
    patch: <T>(endpoint: string, body: any, options?: Omit<ApiRequestOptions, 'method' | 'body'>) =>
        request<T>(endpoint, { ...options, method: 'PATCH', body }),
    put: <T>(endpoint: string, body: any, options?: Omit<ApiRequestOptions, 'method' | 'body'>) =>
        request<T>(endpoint, { ...options, method: 'PUT', body }),
    delete: <T>(endpoint: string, body?: any, options?: Omit<ApiRequestOptions, 'method' | 'body'>) =>
        request<T>(endpoint, { ...options, method: 'DELETE', body }),
};

